import React, { useState, useEffect } from 'react';

const Orders = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // For demo, we'll show mock data
        // In production, fetch from API
        setOrders([
            { id: 1, symbol: 'RELIANCE', type: 'BUY', quantity: 10, price: 2452.70, status: 'COMPLETED', date: '2026-08-09' },
            { id: 2, symbol: 'TCS', type: 'SELL', quantity: 5, price: 4123.45, status: 'PENDING', date: '2026-08-09' },
        ]);
        setLoading(false);
    }, []);

    if (loading) {
        return <div style={{ color: '#8a9bb5' }}>Loading orders...</div>;
    }

    if (orders.length === 0) {
        return (
            <div style={{
                background: '#141b2b',
                padding: '40px',
                borderRadius: '10px',
                border: '1px solid #2a3a5c',
                textAlign: 'center',
                color: '#8a9bb5'
            }}>
                📋 No orders yet
            </div>
        );
    }

    return (
        <div style={{
            background: '#141b2b',
            padding: '20px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c'
        }}>
            <h3 style={{ marginBottom: '15px', color: '#e0e6ed' }}>📋 Order History</h3>
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                    <tr style={{ color: '#8a9bb5', fontSize: '13px', borderBottom: '1px solid #2a3a5c' }}>
                        <th style={{ padding: '10px', textAlign: 'left' }}>Symbol</th>
                        <th style={{ padding: '10px', textAlign: 'center' }}>Type</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Qty</th>
                        <th style={{ padding: '10px', textAlign: 'right' }}>Price</th>
                        <th style={{ padding: '10px', textAlign: 'center' }}>Status</th>
                        <th style={{ padding: '10px', textAlign: 'center' }}>Date</th>
                    </tr>
                </thead>
                <tbody>
                    {orders.map((order) => (
                        <tr key={order.id} style={{ borderBottom: '1px solid #2a3a5c' }}>
                            <td style={{ padding: '10px', fontWeight: 'bold' }}>{order.symbol}</td>
                            <td style={{
                                padding: '10px',
                                textAlign: 'center',
                                color: order.type === 'BUY' ? '#4CAF50' : '#dc3545',
                                fontWeight: 'bold'
                            }}>
                                {order.type}
                            </td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>{order.quantity}</td>
                            <td style={{ padding: '10px', textAlign: 'right' }}>₹{order.price.toFixed(2)}</td>
                            <td style={{
                                padding: '10px',
                                textAlign: 'center',
                                color: order.status === 'COMPLETED' ? '#4CAF50' : '#FFC107'
                            }}>
                                {order.status}
                            </td>
                            <td style={{ padding: '10px', textAlign: 'center', color: '#8a9bb5' }}>
                                {order.date}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default Orders;
